SELECT

FROM `season` s
LEFT JOIN `match` m ON s.match_id = m.id AND m.deleted = 0
WHERE s.deleted = 0

    AND s.match_id = #{query.matchId}


    AND s.season_name LIKE CONCAT('%', #{query.seasonName}, '%')


    AND s.season_year LIKE CONCAT('%', #{query.seasonYear}, '%')


    AND s.status = #{query.status}

ORDER BY s.create_time DESC

    LIMIT #{query.pageSize} OFFSET #{query.offset}

SELECT COUNT(*) FROM `season` s WHERE s.deleted = 0
AND s.match_id = #{query.matchId}
AND s.season_name LIKE CONCAT('%', #{query.seasonName}, '%')
AND s.season_year LIKE CONCAT('%', #{query.seasonYear}, '%')
AND s.status = #{query.status}

